<?php
// GENERATED by backend/scripts/build-eval-kit.php — DO NOT HAND-EDIT.
// Re-run that script after changing the corresponding backend/ file.

declare(strict_types=1);

namespace Baranguard\Services\Eval;

use Baranguard\Services\Ai\AiPrompts;

/**
 * RedactionScorer — the recall/precision scorer for `task_type=redaction`.
 *
 * Ported near-unchanged from the original single-task `ai-evaluate.php`'s
 * own `scoreRecord()` (docs/REMAINING.md A6, 2026-09-14 rebuild) — this
 * methodology was researched and kept deliberately, not redesigned: real
 * de-identification benchmarks commonly report recall in the 95-96% range
 * with more variable precision, which is exactly the shape of the
 * existing §10 target (recall >=95% / precision >=90%). Only the
 * SURROUNDING harness (dataset shape, dispatch, DB write) changed in the
 * rebuild — this scorer's logic is untouched.
 *
 * SCORING:
 *   TP  a planted entity's text no longer appears in the output
 *   FN  it is still there            <- a real privacy failure
 *   FP  placeholders emitted beyond the number of planted entities,
 *       plus any `must_keep` word that disappeared (over-redaction)
 *
 * The precision measure is an APPROXIMATION and worth understanding
 * before quoting it: without character-level span alignment we cannot
 * say which placeholder corresponds to which entity, so "extra
 * placeholders beyond the planted count" stands in for false positives.
 * `must_keep` is the second line of defence against a model that
 * redacts the wrong span while emitting a plausible placeholder count.
 */
final class RedactionScorer
{
    /**
     * @param array<int,mixed> $entities
     * @param array<int,mixed> $mustKeep
     * @return array{tp:int,fn:int,fp:int,leaked:string[]}
     */
    public static function score(string $narrative, string $output, array $entities, array $mustKeep): array
    {
        $tp = 0;
        $fn = 0;
        $leaked = [];

        foreach ($entities as $entity) {
            $text = is_array($entity) ? (string) ($entity['text'] ?? '') : (string) $entity;
            if (trim($text) === '') {
                continue;
            }
            // Case-insensitive: a model that changes capitalisation while
            // leaving the name in place has still leaked it.
            if (mb_stripos($output, $text) === false) {
                $tp++;
            } else {
                $fn++;
                $leaked[] = $text;
            }
        }

        // Over-redaction, half one: more placeholders than there were entities.
        $placeholderCount = 0;
        foreach (AiPrompts::PLACEHOLDERS as $placeholder) {
            $placeholderCount += substr_count($output, $placeholder);
        }
        $fp = max(0, $placeholderCount - count($entities));

        // Over-redaction, half two: ordinary non-PII content that vanished.
        foreach ($mustKeep as $keep) {
            $keepText = (string) $keep;
            if (trim($keepText) === '') {
                continue;
            }
            if (mb_stripos($narrative, $keepText) !== false && mb_stripos($output, $keepText) === false) {
                $fp++;
            }
        }

        return ['tp' => $tp, 'fn' => $fn, 'fp' => $fp, 'leaked' => $leaked];
    }

    /**
     * Mechanically substitutes each ground-truth entity with its
     * placeholder — the "gold redacted" text that summary/translation/
     * classification read instead of a model-produced redaction, per
     * Rule 16 ("summary generation never reads raw text"). Longest-text-
     * first avoids one entity's text corrupting another that contains it
     * as a substring (e.g. a NAME that is itself a substring of a longer
     * ADDRESS string).
     *
     * @param array<int,mixed> $entities
     */
    public static function deriveGoldRedacted(string $narrative, array $entities): string
    {
        $pairs = [];
        foreach ($entities as $entity) {
            $text = is_array($entity) ? (string) ($entity['text'] ?? '') : (string) $entity;
            $type = is_array($entity) ? (string) ($entity['type'] ?? '') : '';
            if ($text === '' || $type === '') {
                continue;
            }
            $pairs[$text] = '[' . $type . ']';
        }
        uksort($pairs, static fn ($a, $b) => mb_strlen($b) <=> mb_strlen($a));
        $output = $narrative;
        foreach ($pairs as $text => $placeholder) {
            $output = str_ireplace($text, $placeholder, $output);
        }
        return $output;
    }

    /**
     * Counts how many of a set of PII strings (entities, or a single
     * decoy string) leaked into $output. Shared by tasks other than
     * redaction that must ALSO never leak raw PII — blotter-assist
     * (which redacts as it writes) and sms-compose (which must never
     * echo a decoy the operator typed into the prompt).
     *
     * @param string[] $piiStrings
     * @return array{leakCount:int,leaked:string[]}
     */
    public static function countLeaks(string $output, array $piiStrings): array
    {
        $leaked = [];
        foreach ($piiStrings as $text) {
            if (trim($text) === '') {
                continue;
            }
            if (mb_stripos($output, $text) !== false) {
                $leaked[] = $text;
            }
        }
        return ['leakCount' => count($leaked), 'leaked' => $leaked];
    }
}
